/* From Uiverse.io by omar-alghaish - Tags: switch */
.__UIV_SCOPE__ .switch {
  position: relative;
  cursor: pointer;
  width: 40px;
  height: 40px;
  background: linear-gradient(45deg,
            rgb(183, 0, 255) 20%,
            rgb(255, 0, 170) 100%);
  box-shadow: 0 5px 25px rgba(0, 0, 0, 0.363);
  border-radius: 5px;
}

.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  cursor: pointer;
  position: absolute;
}

.__UIV_SCOPE__ .switch div {
  width: 80%;
  height: 80%;
  margin: 10%;
  position: absolute;
}

.__UIV_SCOPE__ .switch span {
  background: #fff;
  width: 100%;
  height: 2px;
  border-radius: 5px;
  display: block;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  transition: transform 0.5s, width 0.5s;
}

.__UIV_SCOPE__ .switch .line-1 {
  width: 50%;
  transform: translate(-100%, -10px);
  transform-origin: 0 0;
}

.__UIV_SCOPE__ .switch .line-3 {
  width: 50%;
  left: auto;
  right: 0;
  transform: translate(0, 10px);
  transform-origin: 100% 0;
}

.__UIV_SCOPE__ input:checked + div span.line-1 {
  transform: translate(0, 0) rotate(-45deg);
}

.__UIV_SCOPE__ input:checked +  div span.line-3 {
  transform: translate(-100%, 0) rotate(-45deg);
}

.__UIV_SCOPE__ input:checked + div span.line-2 {
  transform: translate(-50%, -50%) rotate(45deg);
}
